function EXTRACT(f, iv, m1, m2):
    require len(m1) == len(m2) and m1 != m2
    require MD_HASH(f, iv, m1) == MD_HASH(f, iv, m2)
    p1, p2 <- m1, m2
    while p1 nonempty and p2 nonempty:
        b1, b2 <- last(p1), last(p2)
        s1 <- MD_HASH(f, iv, p1 without last)
        s2 <- MD_HASH(f, iv, p2 without last)
        if (s1, b1) != (s2, b2):
            return ((s1, b1), (s2, b2))   # f(s1,b1) = f(s2,b2)
        p1, p2 <- p1 without last, p2 without last
    # unreachable for distinct equal-length inputs

