function FIND_PRODUCT_COLLISION(S):
    elems <- [x in S : x >= 2]
    seen <- empty map (product -> pair)
    for each unordered pair (a, b) in elems:
        p <- a * b
        if p in seen:
            (c, d) <- seen[p]
            if sorted(a, b) != sorted(c, d):
                return (a, b, c, d)
        else:
            seen[p] <- (a, b)
    return NONE

